"""Scheme content (eligibility, benefits, documents, application steps) for the 29 schemes in the MyGovt catalogue.

SOURCE POLICY
* `ev` lists the fields that were read on an OFFICIAL page on 2026-10-20 (url + what was confirmed).
* Everything else comes from the project's compiled scheme reference (the 30-scheme PDF supplied to the project, which says
  itself that it is a reference to be checked against the latest Government Order) and from secondary reporting; those fields keep
  `verification_status = provisional` and are shown with a notice. Nothing here is a statement of entitlement.
* Amounts are stored with an `amount_status`: verified_current / historical / unverified / varies / not_applicable.
* Document levels: required (named by an official source for this scheme) / conditional / category_specific / recommended / unverified.
"""
REF = "MyGovt compiled scheme reference (20 Oct 2026) - not an official source"
CHECK = "2026-10-20"


def S(code, name, name_ta, dept_text, dept_id, category, level, purpose, desc, desc_ta, benefits_summary,
      eligibility, exclusions, benefits, docs, steps, apply_url, official_url, sources, notes, ev=None,
      beneficiaries=None, existing=False, how_note=None):
    return dict(code=code, name=name, name_ta=name_ta, dept_text=dept_text, dept_id=dept_id, category=category, level=level, purpose=purpose,
                desc=desc, desc_ta=desc_ta, benefits_summary=benefits_summary, eligibility=eligibility, exclusions=exclusions, benefits=benefits,
                docs=docs, steps=steps, apply_url=apply_url, official_url=official_url, sources=sources, notes=notes, ev=ev or {},
                beneficiaries=beneficiaries, existing=existing, how_note=how_note)


def B(btype, description, amount=None, freq=None, status="unverified", conditions=None):
    return dict(type=btype, description=description, amount=amount, frequency=freq, amount_status=status, conditions=conditions)


def D(name, level="unverified", note=None):
    return dict(name=name, level=level, note=note)


